  sent_to: AlertRecipient[];
  send_error: string | null;

  acknowledged_by: string | null;
  acknowledged_at: string | null;
  action_taken: string | null;

  created_at: string;
}

export interface AlertRecipient {
  user_id: string;
  email: string;
  method: 'email' | 'in_app' | 'whatsapp';
  sent_at: string;
}

// ============================================================================
// Form Types
// ============================================================================

