interface IngestOptions {
  projectId: string;
  discipline?: Discipline | 'all';
  sinceDate?: string;
  dryRun?: boolean;
}

interface IngestResult {
  projectId: string;
  projectName?: string;
  photosFound: number;
  photosIngested: number;
  reviewsCreated: number;
  reviewsUpdated: number;
  errors: string[];
}

interface IngestAllResult {
  projects: IngestResult[];
  totalPhotosIngested: number;
  totalReviewsCreated: number;
  totalReviewsUpdated: number;
  totalErrors: number;
}

/**
 * Ingest QField photos for ALL mapped projects.
 */
export async function ingestAllQFieldPhotos(opts: { dryRun?: boolean; discipline?: Discipline | 'all' }): Promise<IngestAllResult> {
  const ffProjectIds = Object.values(QFIELD_TO_FIBREFLOW);
  const unique = [...new Set(ffProjectIds)];

  const results: IngestResult[] = [];
  for (const projectId of unique) {
    const r = await ingestQFieldPhotos({ projectId, discipline: opts.discipline, dryRun: opts.dryRun });
    results.push(r);
  }

  return {
    projects: results,
    totalPhotosIngested: results.reduce((s, r) => s + r.photosIngested, 0),
    totalReviewsCreated: results.reduce((s, r) => s + r.reviewsCreated, 0),
    totalReviewsUpdated: results.reduce((s, r) => s + r.reviewsUpdated, 0),
    totalErrors: results.reduce((s, r) => s + r.errors.length, 0),
  };
}

/**
 * Ingest QField photos into the Construction QA system for a single project.
 *
 * Reads from qfield_photo_validations and creates/updates
 * construction_qa_reviews and construction_qa_photos records.
 */
export async function ingestQFieldPhotos(opts: IngestOptions): Promise<IngestResult> {
  const { projectId, discipline = 'all', sinceDate, dryRun = false } = opts;
  const result: IngestResult = {
    projectId,
    photosFound: 0,
    photosIngested: 0,
    reviewsCreated: 0,
    reviewsUpdated: 0,
    errors: [],
  };

  // Look up QField project IDs for this FibreFlow project
  const qfProjectIds = FIBREFLOW_TO_QFIELD[projectId];
  if (!qfProjectIds || qfProjectIds.length === 0) {
    result.errors.push(`No QField project mapping for FibreFlow project ${projectId}`);
    return result;
  }

  log.info('Starting QField ingestion', { projectId, qfProjectIds, discipline, sinceDate, dryRun }, MODULE);

  try {
    // Build work_type filter
    const workTypes: string[] = discipline === 'all'
      ? Object.keys(WORK_TYPE_MAP)
      : [Object.entries(WORK_TYPE_MAP).find(([, v]) => v.discipline === discipline)?.[0]].filter((x): x is string => x !== undefined);

    if (workTypes.length === 0) {
      result.errors.push(`No work types found for discipline: ${discipline}`);
      return result;
    }

    // Build parameterized query
    // $1..$N = qfProjectIds, then workTypes, then optional sinceDate
    let paramIdx = 1;
    const qfPlaceholders = qfProjectIds.map(() => `$${paramIdx++}`).join(', ');
    const wtPlaceholders = workTypes.map(() => `$${paramIdx++}`).join(', ');
    const params: (string | number)[] = [...qfProjectIds, ...workTypes];

    let query = `
      SELECT
        qpv.id AS qfield_id,
        qpv.photo_key,
        qpv.feature_id,
        qpv.feature_type,
        qpv.work_type,
        qpv.project_id AS qfield_project_id,
        qpv.vlm_confidence,
        qpv.vlm_feedback,
        qpv.vlm_raw_response,
        qpv.needs_retake,
        qpv.validated_at,
        qpv.created_at
      FROM qfield_photo_validations qpv
      WHERE qpv.feature_id IS NOT NULL
        AND qpv.project_id IN (${qfPlaceholders})
        AND qpv.work_type IN (${wtPlaceholders})
        AND NOT EXISTS (
          SELECT 1 FROM construction_qa_photos cqp
          WHERE cqp.storage_key = qpv.photo_key
            AND cqp.source = 'qfield'
        )
    `;

    if (sinceDate) {
      query += ` AND qpv.created_at >= $${paramIdx++}`;
      params.push(sinceDate);
    }

    query += ' ORDER BY qpv.created_at ASC';

    const photos = await sql.query(query, params);
    result.photosFound = photos.length;

    if (photos.length === 0) {
      log.info('No new photos to ingest', { projectId }, MODULE);
      return result;
    }

    if (dryRun) {
      log.info('Dry run — skipping writes', { projectId, photosFound: photos.length }, MODULE);
      return result;
    }

    // Deduplicate by photo_key (multiple qfield_photo_validations can reference same photo)
    const seenKeys = new Set<string>();
    const uniquePhotos = photos.filter(p => {
      const pk = p.photo_key as string;
      if (seenKeys.has(pk)) return false;
      seenKeys.add(pk);
      return true;
    });
    result.photosFound = uniquePhotos.length;

    // Group photos by feature_type + feature_id for review creation
    const byFeature = new Map<string, typeof photos>();
    for (const photo of uniquePhotos) {
      const ft = photo.feature_type as string || 'pole';
      const key = `${ft}::${photo.feature_id}`;
      if (!byFeature.has(key)) byFeature.set(key, []);
      byFeature.get(key)!.push(photo);
    }

    // Process each feature group
    for (const [featureKey, featurePhotos] of byFeature) {
      try {
        const sample = featurePhotos[0];
        if (!sample) continue;

        // For activation work_type, derive discipline from actual feature_type
        const rowFeatureType = sample.feature_type as string;
        const mapping = (sample.work_type === 'activation' && rowFeatureType && FEATURE_TYPE_DISCIPLINE[rowFeatureType])
          ? FEATURE_TYPE_DISCIPLINE[rowFeatureType]
          : WORK_TYPE_MAP[sample.work_type as string];
        if (!mapping) continue;

        // Upsert the review record
        const reviewId = await upsertReview(
          projectId,
          mapping.discipline,
          mapping.featureType,
          sample.feature_id as string,
          featurePhotos.length,
          result,
        );

        // Insert photo records and track earliest capture date
        let earliestCapture: Date | null = null;
        for (const photo of featurePhotos) {
          const capturedAt = await insertPhoto(reviewId, projectId, photo);
          if (capturedAt && (!earliestCapture || capturedAt < earliestCapture)) {
            earliestCapture = capturedAt;
          }
          result.photosIngested++;
        }

        // Update review's last_photo_at to earliest capture date
        if (earliestCapture) {
          await sql`
            UPDATE construction_qa_reviews
            SET last_photo_at = LEAST(last_photo_at, ${earliestCapture.toISOString()}::timestamptz)
            WHERE id = ${reviewId}::uuid
          `;
        }
      } catch (err) {
        const msg = `Failed to process feature ${featureKey}: ${(err as Error).message}`;
        log.error('Ingestion error', { error: msg }, MODULE);
        result.errors.push(msg);
      }
    }

    log.info('QField ingestion complete', result, MODULE);
    return result;
  } catch (err) {
    const msg = `Ingestion failed: ${(err as Error).message}`;
    log.error('Fatal ingestion error', { error: msg }, MODULE);
    result.errors.push(msg);
    return result;
  }
}

/**
 * Upsert a construction_qa_reviews record.
 * Returns the review UUID.
 */
async function upsertReview(
  projectId: string,
  discipline: Discipline,
  featureType: FeatureType,
  featureId: string,
  newPhotoCount: number,
  result: IngestResult,
): Promise<string> {
  // Check if review exists
  const existing = await sql`
    SELECT id, photo_count FROM construction_qa_reviews
    WHERE project_id = ${projectId}::uuid
      AND feature_type = ${featureType}
      AND feature_id = ${featureId}
    LIMIT 1
  `;

  if (existing.length > 0) {
    // Update photo count
    // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
    const existingRow = existing[0]!;
    const totalPhotos = Number(existingRow.photo_count) + newPhotoCount;
    await sql`
      UPDATE construction_qa_reviews
      SET photo_count = ${totalPhotos},
          last_photo_at = NOW(),
          updated_at = NOW()
      WHERE id = ${existingRow.id}::uuid
    `;
    result.reviewsUpdated++;
    return existingRow.id as string;
  }

  // Look up zone/PON from the feature table
  let zoneNo: number | null = null;
  let ponNo: number | null = null;

  if (featureType === 'pole') {
    const pole = await sql`
      SELECT zone_no, pon_no FROM poles
      WHERE project_id = ${projectId}::uuid AND pole_number = ${featureId}
      LIMIT 1
    `;
    if (pole.length > 0) {
      // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
      const p = pole[0]!;
      zoneNo = p.zone_no != null ? Number(p.zone_no) : null;
      ponNo = p.pon_no != null ? Number(p.pon_no) : null;
    }
  } else if (featureType === 'cable_span') {
    const span = await sql`
      SELECT zone_no, pon_no FROM cable_spans
      WHERE project_id = ${projectId}::uuid AND span_label = ${featureId}
      LIMIT 1
    `;
    if (span.length > 0) {
      // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
      const s = span[0]!;
      zoneNo = s.zone_no != null ? Number(s.zone_no) : null;
      ponNo = s.pon_no != null ? Number(s.pon_no) : null;
    }
  } else if (featureType === 'joint') {
    const joint = await sql`
      SELECT zone_no, pon_no FROM joints
      WHERE project_id = ${projectId}::uuid AND joint_label = ${featureId}
      LIMIT 1
    `;
    if (joint.length > 0) {
      // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
      const j = joint[0]!;
      zoneNo = j.zone_no != null ? Number(j.zone_no) : null;
      ponNo = j.pon_no != null ? Number(j.pon_no) : null;
    }
  }

  // Create new review
  const newReview = await sql`
    INSERT INTO construction_qa_reviews (
      project_id, discipline, feature_type, feature_id,
      zone_no, pon_no, photo_count, last_photo_at,
      workflow_status, vlm_status, priority
    ) VALUES (
      ${projectId}::uuid, ${discipline}, ${featureType}, ${featureId},
      ${zoneNo}, ${ponNo}, ${newPhotoCount}, NOW(),
      'pending', 'pending', 'normal'
    )
    RETURNING id
  `;

  result.reviewsCreated++;

  // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
  const newReviewRow = newReview[0]!;

  // Log activity
  await sql`
    INSERT INTO construction_qa_activity (review_id, event_type, actor, payload)
    VALUES (
      ${newReviewRow.id}::uuid,
      'photo_ingested',
      'system',
      ${JSON.stringify({ source: 'qfield', photo_count: newPhotoCount })}::jsonb
    )
  `;

  return newReviewRow.id as string;
}

/**
 * Insert a construction_qa_photos record from a QField photo validation row.
 */
async function insertPhoto(
  reviewId: string,
  projectId: string,
  qfPhoto: Record<string, unknown>,
): Promise<Date | null> {
  const photoKey = qfPhoto.photo_key as string;
  const filename = photoKey.split('/').pop() || photoKey;

  // Determine MIME type from extension
  const ext = filename.split('.').pop()?.toLowerCase() || 'jpg';
  const mimeMap: Record<string, string> = {
    jpg: 'image/jpeg', jpeg: 'image/jpeg', png: 'image/png',
    gif: 'image/gif', webp: 'image/webp', heic: 'image/heic',
  };
  const mimeType = mimeMap[ext] || 'image/jpeg';

  // Extract capture date from QField filename
  const capturedAt = parseQFieldCaptureDate(photoKey);

  await sql`
    INSERT INTO construction_qa_photos (
      review_id, project_id, source, storage_key, filename, mime_type,
      vlm_valid, vlm_confidence, vlm_feedback,
      needs_retake, captured_at
    ) VALUES (
      ${reviewId}::uuid,
      ${projectId}::uuid,
      'qfield',
      ${photoKey},
      ${filename},
      ${mimeType},
      ${qfPhoto.vlm_confidence != null ? Number(qfPhoto.vlm_confidence) >= 0.6 : null},
      ${qfPhoto.vlm_confidence != null ? Number(qfPhoto.vlm_confidence) : null},
      ${(qfPhoto.vlm_feedback as string) || null},
      ${Boolean(qfPhoto.needs_retake)},
      ${capturedAt ? capturedAt.toISOString() : null}
    )
  `;

  return capturedAt;
}

/**
 * Field Ops Photo Processing Service
 *
 * Handles downloading WhatsApp construction photos from the bridge and staging
 * them for Firebase upload. Processes photos from field_ops_wa_photos table
 * with pending upload_status.
 *
 * Flow:
 * 1. Query pending photos from field_ops_wa_photos
 * 2. Request download from WhatsApp bridge /api/download
 * 3. Stage file locally and record intended Firebase storage path
 * 4. Update status to 'uploaded' with storage_key
 *
 * @module field-ops/services/fieldOpsPhotoService
 */

import { neon } from '@neondatabase/serverless';
import { createLogger } from '@/lib/logger';
import fs from 'fs';

const logger = createLogger('fieldOpsPhotoService');

// ============================================================================
// Configuration
// ============================================================================

const WA_BRIDGE_DOWNLOAD_URL =
  process.env.WA_BRIDGE_URL || 'http://72.61.197.178:8083/api/download';

// ============================================================================
// Database Connection
// ============================================================================

function getDb() {
  const databaseUrl = process.env.DATABASE_URL;
  if (!databaseUrl) {
    throw new Error('DATABASE_URL environment variable is not set');
  }
  return neon(databaseUrl);
}

// ============================================================================
// Types
// ============================================================================

interface PendingPhoto {
  id: string;
  message_id: string;
  wa_media_id: string;
  wa_group_jid: string;
  group_type: string;
  project: string;
  sender_name: string;
  message_timestamp: string;
  mime_type: string;
  wa_message_id: string;
}

interface DownloadResult {
  success: boolean;
  filename?: string;
  path?: string;
  error?: string;
}

interface FirebaseStageResult {
  success: boolean;
  storageKey?: string;
  error?: string;
}

// ============================================================================
// WhatsApp Bridge Media Download
// ============================================================================

/**
 * Download media from WhatsApp bridge
 */
async function downloadFromBridge(
  messageId: string,
  chatJid: string
): Promise<DownloadResult> {
  try {
    const response = await fetch(WA_BRIDGE_DOWNLOAD_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        message_id: messageId,
        chat_jid: chatJid,
      }),
    });

    const result = await response.json();

    if (result.success && result.path) {
      return {
        success: true,
        filename: result.filename,
        path: result.path,
      };
    }

    return {
      success: false,
      error: result.message || 'Unknown download error',
    };
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : 'Download failed',
    };
  }
}

// ============================================================================
// Firebase Storage Staging
// ============================================================================

/**
 * Stage photo for Firebase upload.
 * Records the intended Firebase storage path; the file is already local from the bridge.
 * Actual Firebase upload runs in a background job when credentials are configured.
 */
async function stageForFirebase(
  localPath: string,
  storagePath: string
): Promise<FirebaseStageResult> {
  try {
    if (!fs.existsSync(localPath)) {
      return { success: false, error: `Local file not found: ${localPath}` };
    }

    logger.info('Photo staged for Firebase upload', { localPath, storagePath });
    return { success: true, storageKey: storagePath };
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : 'Staging failed',
    };
  }
}

// ============================================================================
// Photo Processing
// ============================================================================

/**
 * Get pending photos that need downloading and uploading
 */
export async function getPendingPhotos(limit = 10): Promise<PendingPhoto[]> {
  const sql = getDb();

  const result = await sql`
    SELECT
      p.id,
      p.message_id,
      p.wa_media_id,
      p.wa_group_jid,
      p.group_type,
      p.project,
      p.sender_name,
      p.message_timestamp,
      p.mime_type,
      m.wa_message_id
    FROM field_ops_wa_photos p
    JOIN field_ops_wa_messages m ON p.message_id = m.id
    WHERE p.upload_status = 'pending'
    ORDER BY p.created_at ASC
    LIMIT ${limit}
  `;

  return result as unknown as PendingPhoto[];
}

/**
 * Process a single pending photo: download from bridge + stage for Firebase
 */
export async function processPhoto(
  photo: PendingPhoto
): Promise<{ success: boolean; error?: string }> {
  const sql = getDb();

  // Mark as uploading
  await sql`
    UPDATE field_ops_wa_photos
    SET upload_status = 'uploading', updated_at = NOW()
    WHERE id = ${photo.id}
  `;

  // Step 1: Download from WhatsApp bridge
  logger.info('Downloading photo from bridge', {
    photoId: photo.id,
    messageId: photo.wa_message_id,
  });

  const download = await downloadFromBridge(photo.wa_message_id, photo.wa_group_jid);

  if (!download.success || !download.path) {
    await sql`
      UPDATE field_ops_wa_photos
      SET upload_status = 'failed', upload_error = ${download.error || null}, updated_at = NOW()
      WHERE id = ${photo.id}
    `;
    return { success: false, error: download.error };
  }

  // Step 2: Stage for Firebase
  const date = new Date(photo.message_timestamp).toISOString().split('T')[0];
  const filename = download.filename || `photo_${photo.id}.jpg`;
  const storagePath = `construction-qa/${photo.project}/${date}/${filename}`;

  const stage = await stageForFirebase(download.path, storagePath);

  if (!stage.success) {
    await sql`
      UPDATE field_ops_wa_photos
      SET upload_status = 'failed', upload_error = ${stage.error || null}, updated_at = NOW()
      WHERE id = ${photo.id}
    `;
    return { success: false, error: stage.error };
  }

  // Step 3: Update to uploaded with storage key and local path
  await sql`
    UPDATE field_ops_wa_photos
    SET
      upload_status = 'uploaded',
      storage_key = ${stage.storageKey || null},
      local_path = ${download.path},
      uploaded_at = NOW(),
      updated_at = NOW()
    WHERE id = ${photo.id}
  `;

  logger.info('Photo staged successfully', {
    photoId: photo.id,
    storageKey: stage.storageKey,
  });

  return { success: true };
}

/**
 * Batch process pending photos (download + stage)
 */
export async function processPendingPhotos(limit = 10): Promise<{
  processed: number;
  succeeded: number;
  failed: number;
  errors: string[];
}> {
  const pendingPhotos = await getPendingPhotos(limit);

  const results = {
    processed: 0,
    succeeded: 0,
    failed: 0,
    errors: [] as string[],
  };

  for (const photo of pendingPhotos) {
    results.processed++;

    try {
      const result = await processPhoto(photo);

      if (result.success) {
        results.succeeded++;
      } else {
        results.failed++;
        results.errors.push(`Photo ${photo.id}: ${result.error}`);
      }
    } catch (error) {
      results.failed++;
      results.errors.push(
        `Photo ${photo.id}: ${error instanceof Error ? error.message : 'Unknown error'}`
      );
    }
  }

  logger.info('Batch photo processing complete', {
    processed: results.processed,
    succeeded: results.succeeded,
    failed: results.failed,
  });

  return results;
}

/**
 * EXIF / capture-date utilities for Construction QA photos.
 *
 * Two strategies:
 *   1. parseQFieldCaptureDate — extracts timestamp from QField filename pattern
 *      (no I/O, instant, works for all 5 834 QField photos)
 *   2. extractExifFromBuffer — reads EXIF DateTimeOriginal + GPS from image buffer
 *      (needs sharp + exif-reader, used for future non-QField sources)
 */

import { log } from '@/lib/logger';

const MODULE = 'exif-utils';

/**
 * QField storage keys encode capture time in the filename portion:
 *   projects/.../DCIM/law-poles_20251120145759971.JPG/v20251120130451-5e8d1c2f
 *   Pattern: _YYYYMMDDHHMMSSmmm  (mmm = milliseconds, may be absent)
 *
 * The filename is NOT the last segment (that's the version suffix).
 * We match the timestamp pattern anywhere in the key.
 */
const QF_TS_RE = /_(\d{4})(\d{2})(\d{2})(\d{2})(\d{2})(\d{2})(\d{3})?\.(?:jpg|jpeg|png|gif|webp|heic)/i;

export function parseQFieldCaptureDate(storageKey: string): Date | null {
  const m = QF_TS_RE.exec(storageKey);
  if (!m) return null;

  const [, year, month, day, hour, min, sec, ms] = m;
  const iso = `${year}-${month}-${day}T${hour}:${min}:${sec}.${ms || '000'}Z`;

  const d = new Date(iso);
  if (isNaN(d.getTime())) {
    log.warn('Invalid QField capture date', { storageKey, iso }, MODULE);
    return null;
  }
  return d;
}

interface ExifResult {
  capturedAt?: Date;
  gpsLat?: number;
  gpsLon?: number;
}

/**
 * Extract EXIF metadata from an image buffer using sharp + exif-reader.
 * Returns DateTimeOriginal and GPS coordinates when available.
 */
export async function extractExifFromBuffer(buffer: Buffer): Promise<ExifResult> {
  const result: ExifResult = {};

  try {
    // Dynamic imports to keep module lightweight when only using parseQFieldCaptureDate
    const sharp = (await import('sharp')).default;
    const exifReader = (await import('exif-reader')).default;

    const metadata = await sharp(buffer).metadata();
    if (!metadata.exif) return result;

    const exif = exifReader(metadata.exif);

    // DateTimeOriginal
    if (exif?.Photo?.DateTimeOriginal) {
      const dt = exif.Photo.DateTimeOriginal;
      if (dt instanceof Date && !isNaN(dt.getTime())) {
        result.capturedAt = dt;
      }
    }

    // GPS coordinates
    if (exif?.GPSInfo) {
      const gps = exif.GPSInfo;
      if (gps.GPSLatitude != null && gps.GPSLongitude != null) {
        result.gpsLat = gps.GPSLatitude as number;
        result.gpsLon = gps.GPSLongitude as number;
      }
    }
  } catch (err) {
    log.warn('EXIF extraction failed', { error: (err as Error).message }, MODULE);
  }

  return result;
}

/**
 * POST /api/construction-qa/ingest-qfield
 *
 * Triggers ingestion of QField photos into the Construction QA system.
 * Reads from qfield_photo_validations and creates review + photo records.
 *
 * Auth: session cookie OR x-cron-secret header (for cron jobs)
 *
 * Body: { projectId?, discipline?, sinceDate?, dryRun? }
 *   - projectId: FibreFlow project UUID (optional — omit to ingest ALL mapped projects)
 *   - discipline: 'civil' | 'optical' | 'splicing' | 'all' (default: 'all')
 *   - sinceDate: ISO date string to filter photos (optional)
 *   - dryRun: boolean (default: false)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { ingestQFieldPhotos, ingestAllQFieldPhotos } from '@/modules/construction-qa/services/qfieldIngestionService';

const CRON_SECRET = process.env.CRON_SECRET || '';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || 'unknown', ['POST']);
  }

  // Auth: cron secret or session cookie
  const cronSecret = req.headers['x-cron-secret'] || req.query.secret;
  if (cronSecret !== CRON_SECRET && !req.headers.cookie) {
    return apiResponse.unauthorized(res, 'Invalid cron secret');
  }

  try {
    const { projectId, discipline, sinceDate, dryRun } = req.body;

    if (!projectId) {
      // Ingest all mapped projects
      const result = await ingestAllQFieldPhotos({
        discipline: discipline || 'all',
        dryRun: Boolean(dryRun),
      });
      return apiResponse.success(res, { mode: 'all', dryRun: Boolean(dryRun), ...result });
    }

    const result = await ingestQFieldPhotos({
      projectId,
      discipline: discipline || 'all',
      sinceDate,
      dryRun: Boolean(dryRun),
    });

    return apiResponse.success(res, { mode: 'single', dryRun: Boolean(dryRun), ...result });
  } catch (error) {
    log.error('Ingest API error', { module: 'construction-qa', error: (error as Error).message });
    return apiResponse.internalError(res, error);
  }
}

export default handler;

#!/usr/bin/env tsx
/**
 * Backfill captured_at for QField photos from filename timestamps.
 *
 * QField filenames encode the capture time:
 *   law-poles_20251120145759971.JPG → 2025-11-20T14:57:59.971Z
 *
 * This script:
 *   1. Finds all construction_qa_photos WHERE source='qfield' AND captured_at IS NULL
 *   2. Parses capture date from storage_key filename
 *   3. Batch UPDATEs captured_at
 *   4. Updates construction_qa_reviews.last_photo_at to the EARLIEST captured_at per review
 *
 * Usage:
 *   npx tsx scripts/backfill-photo-captured-at.ts          # dry run
 *   npx tsx scripts/backfill-photo-captured-at.ts --apply   # execute
 */

import dotenv from 'dotenv';
dotenv.config({ path: '.env.local' });
import { neon } from '@neondatabase/serverless';

const sql = neon(process.env.DATABASE_URL!);
const BATCH_SIZE = 500;
const applyMode = process.argv.includes('--apply');

/** QField filename pattern: _YYYYMMDDHHMMSSmmm.ext (filename is mid-path, not last segment) */
const QF_TS_RE = /_(\d{4})(\d{2})(\d{2})(\d{2})(\d{2})(\d{2})(\d{3})?\.(?:jpg|jpeg|png|gif|webp|heic)/i;

function parseCaptureDateFromKey(storageKey: string): Date | null {
  const m = QF_TS_RE.exec(storageKey);
  if (!m) return null;

  const [, year, month, day, hour, min, sec, ms] = m;
  const iso = `${year}-${month}-${day}T${hour}:${min}:${sec}.${ms || '000'}Z`;
  const d = new Date(iso);
  return isNaN(d.getTime()) ? null : d;
}

async function main() {
  console.log(`\n=== Backfill captured_at for QField photos ===`);
  console.log(`Mode: ${applyMode ? 'APPLY (writing to DB)' : 'DRY RUN (read-only)'}\n`);

  // Step 1: Find photos needing backfill
  const photos = await sql`
    SELECT id, storage_key
    FROM construction_qa_photos
    WHERE source = 'qfield' AND captured_at IS NULL
    ORDER BY id
  `;

  console.log(`Found ${photos.length} QField photos with NULL captured_at`);

  if (photos.length === 0) {
    console.log('Nothing to backfill. Done.');
    return;
  }

  // Step 2: Parse dates from filenames
  let parsed = 0;
  let skipped = 0;
  const updates: { id: string; capturedAt: string }[] = [];

  for (const photo of photos) {
    const capturedAt = parseCaptureDateFromKey(photo.storage_key as string);
    if (capturedAt) {
      updates.push({ id: photo.id as string, capturedAt: capturedAt.toISOString() });
      parsed++;
    } else {
      skipped++;
    }
  }

  console.log(`Parsed: ${parsed}, Skipped (no pattern match): ${skipped}`);

  if (!applyMode) {
    // Show sample
    const sample = updates.slice(0, 5);
    console.log('\nSample updates:');
    for (const u of sample) {
      const photo = photos.find(p => p.id === u.id);
      console.log(`  ${(photo?.storage_key as string)?.split('/').pop()} → ${u.capturedAt}`);
    }
    console.log(`\nRun with --apply to execute ${updates.length} updates.`);
    return;
  }

  // Step 3: Batch update photos
  console.log(`\nUpdating ${updates.length} photos in batches of ${BATCH_SIZE}...`);
  let totalUpdated = 0;

  for (let i = 0; i < updates.length; i += BATCH_SIZE) {
    const batch = updates.slice(i, i + BATCH_SIZE);

    // Build a VALUES list for batch update
    const values = batch.map((u, idx) => {
      const p1 = idx * 2 + 1;
      const p2 = idx * 2 + 2;
      return `($${p1}::uuid, $${p2}::timestamptz)`;
    }).join(', ');

    const params = batch.flatMap(u => [u.id, u.capturedAt]);

    const updateQuery = `
      UPDATE construction_qa_photos AS p
      SET captured_at = v.captured_at
      FROM (VALUES ${values}) AS v(id, captured_at)
      WHERE p.id = v.id
    `;

    await sql.query(updateQuery, params);
    totalUpdated += batch.length;
    console.log(`  Updated ${totalUpdated}/${updates.length}`);
  }

  // Step 4: Update reviews.last_photo_at to earliest photo captured_at
  console.log('\nUpdating review last_photo_at to earliest photo captured_at...');
  const reviewResult = await sql`
    UPDATE construction_qa_reviews r
    SET last_photo_at = sub.earliest_capture
    FROM (
      SELECT review_id, MIN(captured_at) AS earliest_capture
      FROM construction_qa_photos
      WHERE source = 'qfield' AND captured_at IS NOT NULL
      GROUP BY review_id
    ) sub
    WHERE r.id = sub.review_id
      AND (r.last_photo_at IS NULL OR r.last_photo_at > sub.earliest_capture)
  `;
  console.log(`  Updated ${reviewResult.length ?? 0} reviews`);

  // Step 5: Summary
  const verification = await sql`
    SELECT
      COUNT(*) FILTER (WHERE captured_at IS NOT NULL) AS with_date,
      COUNT(*) FILTER (WHERE captured_at IS NULL) AS without_date
    FROM construction_qa_photos
    WHERE source = 'qfield'
  `;
  const v = verification[0];
  console.log(`\nVerification: ${v?.with_date} with captured_at, ${v?.without_date} without`);
  console.log('Done.');
}

main().catch((err) => {
  console.error('Backfill failed:', err);
  process.exit(1);
});

/**
 * Field Ops Photo Processing Endpoint
 *
 * POST /api/field-ops/process-photos
 *   - Validates x-cron-secret header
 *   - Runs photo download + staging batch (fieldOpsPhotoService)
 *   - Runs VLM validation + cross-reference batch (fieldOpsVlmService)
 *   - Returns combined results
 *
 * Intended for cron invocation every few minutes.
 *
 * @module api/field-ops/process-photos
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { createLogger } from '@/lib/logger';
import { apiResponse } from '@/lib/apiResponse';
import { processPendingPhotos } from '@/modules/field-ops/services/fieldOpsPhotoService';
import { validatePendingPhotos } from '@/modules/field-ops/services/fieldOpsVlmService';

const logger = createLogger('api:field-ops:process-photos');

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
): Promise<void> {
  if (req.method !== 'POST') {
    apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
    return;
  }

  // Validate cron secret
  const cronSecret = req.headers['x-cron-secret'];
  if (!process.env.CRON_SECRET || cronSecret !== process.env.CRON_SECRET) {
    apiResponse.unauthorized(res, 'Invalid or missing cron secret');
    return;
  }

  const { photoLimit = 10, vlmLimit = 5 } = req.body || {};

  logger.info('Starting field-ops photo processing', { photoLimit, vlmLimit });

  try {
    // Phase 1: Download + stage photos from WhatsApp bridge
    const photoResults = await processPendingPhotos(Number(photoLimit));

    logger.info('Photo download batch complete', {
      processed: photoResults.processed,
      succeeded: photoResults.succeeded,
      failed: photoResults.failed,
    });

    // Phase 2: VLM validation + project cross-reference
    const vlmResults = await validatePendingPhotos(Number(vlmLimit));

    logger.info('VLM validation batch complete', {
      processed: vlmResults.processed,
      succeeded: vlmResults.succeeded,
      failed: vlmResults.failed,
    });

    apiResponse.success(res, {
      photos: photoResults,
      vlm: vlmResults,
    });
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : 'Unknown error';
    logger.error('Field-ops photo processing failed', { error: errorMessage });
    apiResponse.internalError(res, error, 'Photo processing pipeline failed');
  }
}

/**
 * Field Ops VLM Validation Service
 *
 * Two-stage AI validation for field_ops_wa_photos (upload_status='uploaded', vlm_processed=false):
 * 1. VLM Visual Analysis — Qwen3-VL-8B inspects photos for discipline-specific QA criteria
 *    and extracts the pole number from visible labels.
 * 2. Project Cross-Reference — Validates the extracted pole number against the project SOW
 *    (poles table) and checks PON stage progression.
 *
 * @module field-ops/services/fieldOpsVlmService
 */

import { neon } from '@neondatabase/serverless';
import { createLogger } from '@/lib/logger';

const logger = createLogger('fieldOpsVlmService');
const VLM_URL = process.env.VLM_SERVICE_URL || 'http://100.96.203.105:8100';
const VLM_MODEL = 'Qwen3-VL-8B-Instruct';

function getDb() {
  if (!process.env.DATABASE_URL) throw new Error('DATABASE_URL not set');
  return neon(process.env.DATABASE_URL);
}

// ============================================================================
// Types
// ============================================================================

interface UploadedPhoto {
  id: string;
  group_type: string;
  project: string;
  storage_key: string;
  local_path: string;
  wa_group_jid: string;
  message_timestamp: string;
}

interface VlmResult {
  extracted_pole_number: string | null;
  vlm_valid: boolean;
  confidence: number;
  issues: string[];
  feedback: string;
}

interface CrossRefResult {
  valid: boolean;
  issues: string[];
  pole_number: string | null;
  zone_no: number | null;
  pon_no: number | null;
}

// ============================================================================
// VLM Prompts
// ============================================================================

const CIVIL_PROMPT = `You are a civil construction QA inspector for fiber network pole installations.
Analyze this photo and respond with ONLY a valid JSON object.
Check: 1) Pole verticality, 2) Depth marker visible, 3) Ground compaction, 4) Stay wires installed, 5) Pole label/number.
JSON format:
{"extracted_pole_number":"POL-001 or null","valid":true,"confidence":0.0,"issues":[],"feedback":"one sentence"}`;

const OPTICAL_PROMPT = `You are a fiber optic construction QA inspector for aerial fiber installations.
Analyze this photo and respond with ONLY a valid JSON object.
Check: 1) Cable tension appropriate, 2) Sag within spec, 3) Splice dome sealed, 4) Cable markings.
JSON format:
{"extracted_pole_number":null,"valid":true,"confidence":0.0,"issues":[],"feedback":"one sentence"}`;

// ============================================================================
// Stage 1: VLM Visual Analysis
// ============================================================================

function parseVlmResponse(text: string): VlmResult {
  try {
    const jsonMatch = text.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      const p = JSON.parse(jsonMatch[0]);
      return {
        extracted_pole_number: p.extracted_pole_number ? String(p.extracted_pole_number) : null,
        vlm_valid: Boolean(p.valid ?? p.pass ?? false),
        confidence: Math.min(1, Math.max(0, Number(p.confidence ?? 0))),
        issues: Array.isArray(p.issues) ? p.issues : [],
        feedback: String(p.feedback || ''),
      };
    }
  } catch { /* fall through */ }

  const lower = text.toLowerCase();
  const valid = lower.includes('pass') || lower.includes('acceptable');
  return {
    extracted_pole_number: null,
    vlm_valid: valid,
    confidence: valid ? 0.5 : 0.2,
    issues: valid ? [] : ['Manual review required — AI could not parse response'],
    feedback: text.slice(0, 300),
  };
}

/**
 * Call Qwen3-VL to analyse a construction photo and extract QA results.
 */
async function runVlmAnalysis(photoPath: string, discipline: string): Promise<VlmResult> {
  const prompt = discipline === 'civil' ? CIVIL_PROMPT : OPTICAL_PROMPT;
  const baseUrl = process.env.NEXT_PUBLIC_BASE_URL || 'http://localhost:3004';
  const imageUrl = photoPath.startsWith('http')
    ? photoPath
    : `${baseUrl}/api/field-ops/photo-proxy?path=${encodeURIComponent(photoPath)}`;

  try {
    const response = await fetch(`${VLM_URL}/v1/chat/completions`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        model: VLM_MODEL,
        messages: [
          {
            role: 'user',
            content: [
              { type: 'image_url', image_url: { url: imageUrl, detail: 'high' } },
              { type: 'text', text: prompt },
            ],
          },
        ],
        max_tokens: 512,
        temperature: 0.1,
      }),
    });

    if (!response.ok) {
      throw new Error(`VLM HTTP ${response.status}: ${await response.text()}`);
    }

    const data = await response.json();
    const text: string = data.choices?.[0]?.message?.content || '';
    return parseVlmResponse(text);
  } catch (error) {
    logger.error('VLM analysis failed', {
      error: error instanceof Error ? error.message : 'Unknown',
      photoPath,
    });
    return {
      extracted_pole_number: null,
      vlm_valid: false,
      confidence: 0,
      issues: [`VLM error: ${error instanceof Error ? error.message : 'Unknown'}`],
      feedback: 'AI validation unavailable — manual review required',
    };
  }
}

// ============================================================================
// Stage 2: Project Cross-Reference
// ============================================================================

/**
 * Validate extracted pole number against the project SOW and PON stage tracking.
 */
async function crossReferenceProject(
  poleNumber: string | null,
  projectName: string
): Promise<CrossRefResult> {
  if (!poleNumber) {
    return { valid: false, issues: ['Could not extract pole number from photo'], pole_number: null, zone_no: null, pon_no: null };
  }

  const sql = getDb();
  const projects = await sql`SELECT id FROM projects WHERE project_name = ${projectName} LIMIT 1`;

  if (projects.length === 0) {
    return { valid: false, issues: [`Project '${projectName}' not found`], pole_number: poleNumber, zone_no: null, pon_no: null };
  }

  const projectRow = projects[0] as Record<string, unknown> | undefined;
  const projectId = projectRow?.id as string | undefined;
  if (!projectId) {
    return { valid: false, issues: [`Project '${projectName}' has no ID`], pole_number: poleNumber, zone_no: null, pon_no: null };
  }

  const poles = await sql`
    SELECT zone_no, pon_no FROM poles
    WHERE project_id = ${projectId}::uuid AND pole_number = ${poleNumber}
    LIMIT 1
  `;

  if (poles.length === 0) {
    return { valid: false, issues: [`Pole ${poleNumber} not in SOW for '${projectName}'`], pole_number: poleNumber, zone_no: null, pon_no: null };
  }

  const poleRow = poles[0] as Record<string, unknown> | undefined;
  const ponNo = poleRow?.pon_no ? Number(poleRow.pon_no) : null;
  const zoneNo = poleRow?.zone_no ? Number(poleRow.zone_no) : null;
  const issues: string[] = [];

  if (ponNo !== null) {
    const stages = await sql`
      SELECT overall_stage FROM pon_stage_tracking
      WHERE project_id = ${projectId}::uuid AND pon_no = ${ponNo}
      LIMIT 1
    `;
    if (stages.length > 0) {
      const stageRow = stages[0] as Record<string, unknown> | undefined;
      const stage = stageRow?.overall_stage as string | undefined;
      if (stage === 'design' || stage === 'planning') {
        issues.push(`PON ${ponNo} is in '${stage}' stage — pole work may be premature`);
      }
    }
  }

  return { valid: issues.length === 0, issues, pole_number: poleNumber, zone_no: zoneNo, pon_no: ponNo };
}

// ============================================================================
// Exports
// ============================================================================

/**
 * Run VLM + cross-reference validation for a single uploaded photo.
 * Updates field_ops_wa_photos with all results.
 */
export async function validatePhoto(photo: UploadedPhoto): Promise<{ success: boolean; error?: string }> {
  const sql = getDb();
  const discipline = photo.group_type;

  try {
    const vlmResult = await runVlmAnalysis(photo.local_path || photo.storage_key, discipline);

    let crossRef: CrossRefResult = { valid: true, issues: [], pole_number: null, zone_no: null, pon_no: null };
    if (discipline === 'civil' && photo.project) {
      crossRef = await crossReferenceProject(vlmResult.extracted_pole_number, photo.project);
    }

    await sql`
      UPDATE field_ops_wa_photos SET
        vlm_processed = true,
        vlm_valid = ${vlmResult.vlm_valid},
        vlm_confidence = ${vlmResult.confidence},
        vlm_issues = ${JSON.stringify(vlmResult.issues)}::jsonb,
        vlm_feedback = ${vlmResult.feedback},
        vlm_processed_at = NOW(),
        cross_ref_valid = ${crossRef.valid},
        cross_ref_issues = ${JSON.stringify(crossRef.issues)}::jsonb,
        matched_pole_number = ${crossRef.pole_number},
        matched_zone_no = ${crossRef.zone_no},
        matched_pon_no = ${crossRef.pon_no},
        updated_at = NOW()
      WHERE id = ${photo.id}
    `;

    logger.info('Photo validation complete', {
      photoId: photo.id,
      discipline,
      vlmValid: vlmResult.vlm_valid,
      crossRefValid: crossRef.valid,
      poleNumber: crossRef.pole_number,
    });

    return { success: true };
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : 'Unknown error';
    logger.error('Photo validation failed', { photoId: photo.id, error: errorMessage });
    return { success: false, error: errorMessage };
  }
}

/**
 * Batch validate uploaded photos pending VLM processing
 */
export async function validatePendingPhotos(limit = 5): Promise<{
  processed: number;
  succeeded: number;
  failed: number;
}> {
  const sql = getDb();
  const photos = await sql`
    SELECT id, group_type, project, storage_key, local_path, wa_group_jid, message_timestamp
    FROM field_ops_wa_photos
    WHERE upload_status = 'uploaded' AND vlm_processed = false
    ORDER BY created_at ASC
    LIMIT ${limit}
  `;

  const results = { processed: 0, succeeded: 0, failed: 0 };

  for (const photo of photos) {
    results.processed++;
    try {
      const result = await validatePhoto(photo as unknown as UploadedPhoto);
      if (result.success) results.succeeded++;
      else results.failed++;
    } catch {
      results.failed++;
    }
  }

  logger.info('Batch VLM validation complete', results);
  return results;
}

/**
 * POST /api/qfield/validate-photo
 * Real-time photo validation for QField plugin
 *
 * Accepts a base64 image directly and returns immediate validation feedback.
 * Optimized for field use with minimal latency.
 *
 * Authentication: API key (X-API-Key header) for plugin use
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';

// VLM service configuration
const VLM_API_BASE = process.env.VLM_API_URL || 'http://100.96.203.105:8100';
const VLM_API_ENDPOINT = `${VLM_API_BASE}/v1/chat/completions`;
const VLM_MODEL = 'Qwen/Qwen3-VL-8B-Instruct';
